// stlport
//
// std::sort helpers instantiated for PartitionSolver's pair<ObjectID UnsignedInt> vectors with its greater_than
// function-pointer comparator (0x00566EEA..0x005674E3): retail holds one size-optimised (/O1) copy of each.
// The anchor below only makes this TU instantiate them; it is not retail code.
//
#include "PreRTS.h"	// This must go first in EVERY cpp file int the GameEngine
#include "Common/PartitionSolver.h"

// Declare the rowed copy_backward so this TU calls retail's copy at 0x004C72FE
// (VectorPairObjectIDCopyBackward.cpp) instead of emitting its own COMDAT copy.
namespace _STL { template <> PairObjectIDAndUInt *copy_backward<PairObjectIDAndUInt *, PairObjectIDAndUInt *>(PairObjectIDAndUInt *, PairObjectIDAndUInt *, PairObjectIDAndUInt *); }

#pragma inline_depth(0)
// ?_bfmePartitionSortAnchor@@YAXPAU?$pair@W4ObjectID@@I@_STL@@0P6A_NU12@0@Z@Z absent-from-retail
void _bfmePartitionSortAnchor(PairObjectIDAndUInt *first, PairObjectIDAndUInt *last, Bool (*cmp)(PairObjectIDAndUInt, PairObjectIDAndUInt))
{
	std::sort(first, last, cmp);
}
// ?_bfmePartitionUnguardedAnchor@@YAXPAU?$pair@W4ObjectID@@I@_STL@@0P6A_NU12@0@Z@Z absent-from-retail
void _bfmePartitionUnguardedAnchor(PairObjectIDAndUInt *first, PairObjectIDAndUInt *last, Bool (*cmp)(PairObjectIDAndUInt, PairObjectIDAndUInt))
{
	_STL::__unguarded_insertion_sort(first, last, cmp);
}
